// Generates components/crossly/sources/<slug>/ from scripts/events.json
// (the event catalog + samples in https://crossly.net/docs/api-webhooks).
// Run: node scripts/generate-sources.mjs   (generated files are committed)
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const events = JSON.parse(fs.readFileSync(path.join(root, "scripts/events.json"), "utf8"));
const sourcesDir = path.join(root, "components/crossly/sources");

export const SOURCES = {
  "sale.detected": ["new-sale-detected", "New Sale Detected", "`Sale ${d.platform} $${d.salePrice} (order ${d.orderId})`"],
  "order.created": ["new-order-created", "New Order Created", "`Order ${d.platform} ${d.platformOrderId || d.orderId}${d.sku ? ` ${d.sku}` : \"\"}`"],
  "order.address_available": ["order-address-available", "Order Buyer Address Available", "`Address ready for order ${d.orderId}`"],
  "order.shipped": ["order-shipped", "Order Shipped", "`Order ${d.orderId} shipped${d.trackingNumber ? ` (${d.carrier} ${d.trackingNumber})` : \"\"}`"],
  "order.delivered": ["order-delivered", "Order Delivered", "`Order ${d.orderId} delivered`"],
  "order.cancelled": ["order-cancelled", "Order Cancelled", "`Order ${d.orderId} cancelled`"],
  "order.refunded": ["order-refunded", "Order Refunded", "`Order ${d.orderId} refunded $${d.amount}${d.full ? \" (full)\" : \"\"}`"],
  "refund.issued": ["refund-issued", "Refund Issued", "`Refund $${d.amount} on order ${d.orderId}`"],
  "return.requested": ["return-requested", "Return Requested", "`Return requested on order ${d.orderId}: ${d.reason}`"],
  "return.resolved": ["return-resolved", "Return Resolved", "`Return ${d.returnId} ${d.outcome}`"],
  "listing.created": ["new-listing-created", "New Listing Published", "`Listing ${d.listingId} live on ${d.platform}`"],
  "listing.price_changed": ["listing-price-changed", "Listing Price Changed", "`Listing ${d.listingId} ${d.oldPrice} -> ${d.newPrice}`"],
  "listing.delisted": ["listing-delisted", "Listing Delisted", "`Listing ${d.listingId} delisted on ${d.platform}`"],
  "inventory.quantity_changed": ["stock-changed", "Stock Changed", "`${d.sku || d.inventoryItemId}: ${d.quantityAvailable} available${d.soldOut ? \" (sold out)\" : \"\"}`"],
  "offer.received": ["new-offer-received", "New Offer Received", "`Offer $${(d.offerCents / 100).toFixed(2)} on ${d.platform} from ${d.buyerHandle}`"],
  "offer.accepted": ["offer-accepted", "Offer Accepted", "`Offer ${d.offerId} accepted`"],
  "offer.declined": ["offer-declined", "Offer Declined", "`Offer ${d.offerId} declined`"],
  "offer.countered": ["offer-countered", "Offer Countered", "`Offer ${d.offerId} countered at $${(d.counterCents / 100).toFixed(2)}`"],
  "message.received": ["new-message-received", "New Buyer Message", "`Message from ${d.buyerUsername} on ${d.platform}`"],
  "connection.disconnected": ["connection-lost", "Marketplace Connection Lost", "`${d.platform} connection lost: ${d.reason}`"],
  "automation.failed": ["automation-failed", "Automation Failed", "`Automation ${d.ruleName} failed`"],
};

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  for (const [event, [slug, name, summary]] of Object.entries(SOURCES)) {
    const meta = events[event];
    if (!meta) throw new Error(`events.json has no ${event}`);
    const dir = path.join(sourcesDir, slug);
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, "test-event.mjs"), `export default ${JSON.stringify(meta.sample, null, 2)};\n`);
    fs.writeFileSync(path.join(dir, `${slug}.mjs`), `// Generated by scripts/generate-sources.mjs — do not edit by hand.
import common from "../common/webhook.mjs";
import sampleEmit from "./test-event.mjs";

export default {
  ...common,
  key: "crossly-${slug}",
  name: "${name} (Instant)",
  description: ${JSON.stringify(`Emit new event when Crossly sends \`${event}\`: ${meta.description} [See the documentation](https://crossly.net/docs/api-webhooks#event-catalog)`)},
  version: "0.0.1",
  type: "source",
  dedupe: "unique",
  methods: {
    ...common.methods,
    getEvent() {
      return "${event}";
    },
    getSummary({ data: d = {} }) {
      return ${summary};
    },
  },
  sampleEmit,
};
`);
  }
  console.log(`generated ${Object.keys(SOURCES).length} sources`);
}
